script:
/* =========================================================
   SALES VS STOCK CUSTOM HTML BLOCK
========================================================= */

(function () {

    const loader =
        root_element.querySelector(
            ".loader"
        );

    const tableContainer =
        root_element.querySelector(
            ".table-container"
        );

    const monthFilter =
        root_element.querySelector(
            ".month-filter"
        );


    if (
        !loader ||
        !tableContainer ||
        !monthFilter
    ) {

        console.error(
            "Sales vs Stock: required elements missing"
        );

        return;
    }


    /* =====================================================
       STYLES
    ===================================================== */

    const thStyle =
        `
        padding:8px 12px;
        text-align:left;
        border-bottom:1px solid #ddd;
        font-weight:600;
        `;


    const tdStyle =
        `
        padding:8px 12px;
        border-bottom:1px solid #eee;
        vertical-align:middle;
        `;


    /* =====================================================
       HELPERS
    ===================================================== */

    function escape(value) {

        return frappe.utils.escape_html(
            String(value ?? "")
        );
    }


    function getValue(row, fields) {

        for (const field of fields) {

            if (
                row[field] !== undefined &&
                row[field] !== null &&
                row[field] !== ""
            ) {

                return row[field];
            }
        }

        return "";
    }


    function getItemName(row) {

        return getValue(
            row,
            [
                "custom_barcode_code",
                "item_name",
                "item_code",
                "item",
                "style_no",
                "style"
            ]
        ) || "-";
    }


    function getImage(row) {

        return getValue(
            row,
            [
                "image_url",
                "image",
                "item_image"
            ]
        );
    }


    function getSalesQty(row) {

        return Number(
            getValue(
                row,
                [
                    "sales_qty",
                    "qty",
                    "total_qty",
                    "sales_quantity"
                ]
            )
        ) || 0;
    }


    function getStockQty(row) {

        return Number(
            getValue(
                row,
                [
                    "stock_qty",
                    "actual_qty",
                    "qty"
                ]
            )
        ) || 0;
    }


    function getMonth(row) {

        return getValue(
            row,
            [
                "month",
                "month_name"
            ]
        ) || "";
    }


    /* =====================================================
       AVATAR
    ===================================================== */

    function getAvatar(name) {

        const initial =
            (name || "?")
                .charAt(0)
                .toUpperCase();


        const colors = [
            "#e74c3c",
            "#3498db",
            "#2ecc71",
            "#f39c12",
            "#9b59b6",
            "#1abc9c",
            "#e67e22",
            "#e91e63"
        ];


        const index =
            (name || "")
                .charCodeAt(0) %
            colors.length;


        return `
            <div
                style="
                    width:70px;
                    height:70px;
                    background:${colors[index]};
                    border-radius:6px;
                    display:flex;
                    align-items:center;
                    justify-content:center;
                    font-size:28px;
                    font-weight:700;
                    color:#fff;
                    font-family:sans-serif;
                "
            >
                ${escape(initial)}
            </div>
        `;
    }


    /* =====================================================
       IMAGE
    ===================================================== */

    function getImageHTML(row, itemName) {

        const image =
            getImage(row);


        if (!image) {

            return getAvatar(
                itemName
            );
        }


        return `
            <div
                style="
                    width:70px;
                    height:70px;
                "
            >

                <img
                    src="${escape(image)}"
                    style="
                        width:70px;
                        height:70px;
                        object-fit:cover;
                        border-radius:6px;
                    "
                    onerror="
                        this.parentElement.innerHTML =
                        ${JSON.stringify(
                            getAvatar(itemName)
                        )};
                    "
                >

            </div>
        `;
    }


    /* =====================================================
       STATUS
    ===================================================== */

    function getStatus(
        salesQty,
        stockQty
    ) {

        /*
         * Stock 0 => Low Stock
         */

        if (stockQty <= 0) {

            return "Low Stock";
        }


        /*
         * Stock less/equal sales
         */

        if (stockQty <= salesQty) {

            return "Low Stock";
        }


        return "In Stock";
    }


    /* =====================================================
       RENDER TABLE
    ===================================================== */

    function renderTable(
        rows,
        selectedMonth
    ) {

        loader.style.display =
            "none";


        if (
            !rows ||
            !rows.length
        ) {

            tableContainer.innerHTML = `
                <p style="color:#888;">
                    No data found.
                </p>
            `;

            return;
        }


        /*
         * Filter month on frontend.
         *
         * This makes dropdown instant and avoids
         * another report API call.
         */

        let filtered =
            rows.slice();


        if (selectedMonth) {

            const monthNumber =
                Number(selectedMonth);


            filtered =
                filtered.filter(row => {

                    const month =
                        Number(
                            row.month_number ||
                            row.month_no ||
                            row.month
                        );


                    return (
                        month ===
                        monthNumber
                    );
                });
        }


        /*
         * Remove duplicate item + month
         */

        const unique = {};


        filtered.forEach(row => {

            const item =
                getItemName(row);


            const month =
                getMonth(row);


            const key =
                `${item}__${month}`;


            if (!unique[key]) {

                unique[key] = {

                    ...row,

                    sales_qty:
                        getSalesQty(row),

                    stock_qty:
                        getStockQty(row)
                };

            } else {

                /*
                 * If same item/month occurs more than once,
                 * combine sales.
                 */

                unique[key].sales_qty +=
                    getSalesQty(row);
            }
        });


        const finalRows =
            Object.values(unique);


        if (!finalRows.length) {

            tableContainer.innerHTML = `
                <p style="color:#888;">
                    No data found for selected month.
                </p>
            `;

            return;
        }


        let html = `

            <div style="overflow-x:auto;">

                <table
                    style="
                        width:100%;
                        border-collapse:collapse;
                    "
                >

                    <thead>

                        <tr
                            style="
                                background:#f5f5f5;
                            "
                        >

                            <th style="${thStyle}">
                                Image
                            </th>

                            <th style="${thStyle}">
                                Item
                            </th>

                            <th style="${thStyle}">
                                Month
                            </th>

                            <th style="${thStyle}">
                                Sales Qty
                            </th>

                            <th style="${thStyle}">
                                Stock Qty
                            </th>

                            <th style="${thStyle}">
                                Status
                            </th>

                        </tr>

                    </thead>

                    <tbody>
        `;


        finalRows.forEach(row => {

            const itemName =
                getItemName(row);


            const salesQty =
                getSalesQty(row);


            const stockQty =
                getStockQty(row);


            const month =
                getMonth(row);


            const status =
                getStatus(
                    salesQty,
                    stockQty
                );


            const imageHTML =
                getImageHTML(
                    row,
                    itemName
                );


            const statusColor =
                status === "Low Stock"
                    ? "#e74c3c"
                    : "#27ae60";


            html += `

                <tr>

                    <td style="${tdStyle}">
                        ${imageHTML}
                    </td>

                    <td style="${tdStyle}">
                        ${escape(itemName)}
                    </td>

                    <td style="${tdStyle}">
                        ${escape(month)}
                    </td>

                    <td style="${tdStyle}">
                        ${salesQty}
                    </td>

                    <td style="${tdStyle}">
                        ${stockQty}
                    </td>

                    <td style="${tdStyle}">

                        <span
                            style="
                                background:${statusColor}20;
                                color:${statusColor};
                                padding:3px 10px;
                                border-radius:12px;
                                font-size:12px;
                                font-weight:600;
                            "
                        >
                            ${escape(status)}
                        </span>

                    </td>

                </tr>
            `;
        });


        html += `

                    </tbody>

                </table>

            </div>
        `;


        tableContainer.innerHTML =
            html;
    }


    /* =====================================================
       RECEIVE DATA FROM DASHBOARD
    ===================================================== */

    function receiveData(event) {

        const detail =
            event.detail || {};


        const result =
            detail.result;


        const filters =
            detail.filters || {};


        /*
         * Store latest result.
         */

        window.__sellingDashboardSalesVsStock =
            result &&
            Array.isArray(result.result)
                ? result.result
                : [];


        /*
         * Set month from date range.
         */

        let month = "";


        if (filters.to_date) {

            const date =
                new Date(
                    filters.to_date
                );


            if (
                !isNaN(
                    date.getTime()
                )
            ) {

                month =
                    date.getMonth() + 1;
            }
        }


        /*
         * If current selected month is valid,
         * keep it.
         */

        if (
            monthFilter.value
        ) {

            month =
                monthFilter.value;
        }


        monthFilter.value =
            month
                ? String(month)
                : "";


        renderTable(
            window.__sellingDashboardSalesVsStock,
            monthFilter.value
        );
    }


    document.addEventListener(
        "sellingDashboardSalesVsStockData",
        receiveData
    );


    /* =====================================================
       MONTH CHANGE
    ===================================================== */

    monthFilter.addEventListener(
        "change",
        function () {

            const rows =
                window.__sellingDashboardSalesVsStock ||
                [];


            renderTable(
                rows,
                this.value
            );
        }
    );


    /* =====================================================
       INITIAL FALLBACK
    ===================================================== */

    setTimeout(function () {

        /*
         * Dashboard may already have sent data.
         */

        if (
            window.__sellingDashboardSalesVsStock
        ) {

            renderTable(
                window.__sellingDashboardSalesVsStock,
                monthFilter.value
            );
        }

    }, 500);

})();

style:
#sales-stock-wrapper {
    font-family: Arial, sans-serif;
}

/* Loader */
#loader {
    text-align: center;
    padding: 20px;
    color: #666;
}

/* Table */
.sales-table {
    width: 100%;
    border-collapse: collapse;
    background: #fff;
}

.sales-table th {
    background: #f7f7f7;
    padding: 10px;
    font-weight: 600;
    text-align: left;
    border-bottom: 1px solid #ddd;
}

.sales-table td {
    padding: 10px;
    border-bottom: 1px solid #eee;
    vertical-align: middle;
}

/* Image */
.img-box {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 60px;
}

.img-box img {
    width: 50px;
    height: 50px;
    object-fit: cover;
    border-radius: 6px;
    border: 1px solid #ddd;
}

/* Status badges */
.badge {
    padding: 4px 8px;
    border-radius: 6px;
    font-size: 12px;
    font-weight: 500;
}

.in-stock {
    background: #d4edda;
    color: #155724;
}

.low-stock {
    background: #f8d7da;
    color: #721c24;
}

/* Responsive */
@media (max-width: 768px) {
    .sales-table th,
    .sales-table td {
        font-size: 12px;
        padding: 6px;
    }
}

