// ✅ Frappe shorten_number null crash fix
(function patchFrappe() {
  function applyPatch() {
    if (frappe && frappe.utils && frappe.utils.shorten_number) {
      var _orig = frappe.utils.shorten_number;
      frappe.utils.shorten_number = function(number) {
        if (number === null || number === undefined) return '0';
        return _orig.apply(this, arguments);
      };
    }
  }
  if (typeof frappe !== 'undefined') {
    applyPatch();
  } else {
    setTimeout(applyPatch, 1000);
  }
})();
var sel = function(id) {

    var el = document.getElementById(id);

    if (el) {
        return el;
    }

    if (
        typeof root_element !== "undefined" &&
        root_element
    ) {
        return root_element.querySelector("#" + id);
    }

    return null;
};
var drState = {
  preset     : 'thismonth',
  from       : '',
  to         : '',
  view       : 'qty',
  company    : '',
  dropOpen   : false,
  customOpen : false
};

var PRESET_IDS = ['last3', 'last7', 'thismonth', 'prevmonth', 'finyr', 'custom'];

function fmt(d) {
  return d.toLocaleDateString('en-IN', {
    day: 'numeric', month: 'short', year: 'numeric'
  });
}

function isoDate(d) {
  return d.getFullYear() + '-' +
         String(d.getMonth() + 1).padStart(2, '0') + '-' +
         String(d.getDate()).padStart(2, '0');
}

function getPresetDates(p) {
  var now = new Date();
  var y = now.getFullYear(), m = now.getMonth();
  if (p === 'last3')     { var f = new Date(now); f.setDate(f.getDate() - 3);  return [f, new Date(now)]; }
  if (p === 'last7')     { var f = new Date(now); f.setDate(f.getDate() - 7);  return [f, new Date(now)]; }
  if (p === 'thismonth') { return [new Date(y, m, 1),     new Date(y, m + 1, 0)]; }
  if (p === 'prevmonth') { return [new Date(y, m - 1, 1), new Date(y, m, 0)];  }
  if (p === 'finyr')     { var fy = m >= 3 ? y : y - 1; return [new Date(fy, 3, 1), new Date(fy + 1, 2, 31)]; }
  return null;
}

(function injectStyle() {
  var styleId = 'dr-silent-style';
  if (!document.getElementById(styleId)) {
    var style = document.createElement('style');
    style.id = styleId;
    style.textContent = [
      // ✅ Screen se bahar move + invisible — display:none nahi (button click fail hota)
      '.dr-offscreen { position: fixed !important; top: -9999px !important; left: -9999px !important; opacity: 0 !important; pointer-events: none !important; }',
      // ✅ Backdrop hamesha hide — dialog kabhi screen par nahi dikhega
      '.modal-backdrop { display: none !important; }',
      // ✅ Body scroll lock nahi hona chahiye
      'body.modal-open { overflow: auto !important; padding-right: 0 !important; }'
    ].join(' ');
    document.head.appendChild(style);
  }
})();

function openDropdown() {
  drState.dropOpen = true;
  sel('dr-dropdown').classList.add('open');
  sel('dr-chevron').classList.add('open');
}

function closeDropdown() {
  drState.dropOpen   = false;
  drState.customOpen = false;
  sel('dr-dropdown').classList.remove('open');
  sel('dr-chevron').classList.remove('open');
  sel('dr-custom-box').classList.remove('open');
}

function toggleDropdown() {
  drState.dropOpen ? closeDropdown() : openDropdown();
}

function setActiveOption(p) {
  PRESET_IDS.forEach(function(id) {
    var el = sel('dr-opt-' + id);
    if (el) el.classList.remove('dr-active');
  });
  var active = sel('dr-opt-' + p);
  if (active) active.classList.add('dr-active');
}

function selectPreset(p) {
  drState.preset = p;
  setActiveOption(p);
  if (p === 'custom') {
    drState.customOpen = !drState.customOpen;
    sel('dr-custom-box').classList.toggle('open', drState.customOpen);
    sel('dr-btn-label').textContent = 'Custom Range';
  } else {
    drState.customOpen = false;
    sel('dr-custom-box').classList.remove('open');
    var dates = getPresetDates(p);
    drState.from = isoDate(dates[0]);
    drState.to   = isoDate(dates[1]);
    sel('dr-btn-label').textContent = fmt(dates[0]) + ' \u2013 ' + fmt(dates[1]);
  }
}

function refreshDashboardChart(payload) {

  var charts = [
    'Sales Trend',
    'Sales Progress',
    'Top Selling Items Chart',
    'Least Selling Items Chart',
    'Sales vs Stock'
  ];

  var index = 0;

  function hideBackdrop() {
    document.querySelectorAll('.modal-backdrop').forEach(function(el) {
      el.style.setProperty('display', 'none', 'important');
    });
    document.body.classList.remove('modal-open');
    document.body.style.removeProperty('overflow');
    document.body.style.removeProperty('padding-right');
  }

  function processNext() {
    if (index >= charts.length) {
      document.querySelectorAll('.modal-backdrop').forEach(function(el) { el.remove(); });
      document.body.classList.remove('modal-open');
      // ✅ Sirf ek alert — saare charts done hone ke baad
      frappe.show_alert({ message: '\u2714 Charts updated', indicator: 'green' }, 3);
      return;
    }

    var chartName = charts[index];
    index++;

    var filterBtn = null;
    document.querySelectorAll('.dashboard-widget-box').forEach(function(el) {
      var titleEl = el.querySelector('.ellipsis');
      if (titleEl && titleEl.textContent.trim() === chartName) {
        filterBtn = el.querySelector('.filter-chart');
      }
    });

    if (!filterBtn) {
      processNext();
      return;
    }

    // Pehle koi open dialog ho toh band karo
    try {
      if (cur_dialog && cur_dialog.$wrapper) {
        cur_dialog.$wrapper.removeClass('dr-offscreen');
        cur_dialog.hide();
      }
    } catch(e) {}

    // ✅ Delay 200ms → 50ms
    setTimeout(function() {

      // MutationObserver — backdrop aate hi turant hide karo
      var observer = new MutationObserver(function(mutations) {
        mutations.forEach(function(m) {
          m.addedNodes.forEach(function(node) {
            if (!node.classList) return;
            if (node.classList.contains('modal-backdrop')) {
              node.style.setProperty('display', 'none', 'important');
            }
            // ✅ Dialog DOM mein aate hi offscreen move karo
            if (node.classList.contains('modal') && node.querySelector('.modal-dialog')) {
              node.classList.add('dr-offscreen');
            }
          });
        });
        hideBackdrop();
      });
      observer.observe(document.body, { childList: true });

      filterBtn.click();

      var attempts = 0;
      var poll = setInterval(function() {
        attempts++;

        // ✅ Timeout 60*80ms=4.8s → 40*50ms=2s
        if (attempts > 40) {
          clearInterval(poll);
          observer.disconnect();
          hideBackdrop();
          processNext();
          return;
        }

        if (!cur_dialog || !cur_dialog.fields_dict) return;
        if (Object.keys(cur_dialog.fields_dict).length < 2) return;

        var dTitle = cur_dialog.title || '';
        var isFilterDialog = dTitle.toLowerCase().indexOf('set filter') !== -1;

        if (!isFilterDialog) {
          clearInterval(poll);
          observer.disconnect();
          try { cur_dialog.hide(); } catch(e) {}
          hideBackdrop();
          processNext();
          return;
        }

        clearInterval(poll);
        observer.disconnect();

        // ✅ Dialog offscreen move karo — invisible par DOM mein present
        hideBackdrop();
        if (cur_dialog.$wrapper) {
          cur_dialog.$wrapper.addClass('dr-offscreen');
        }

        // Values set karo
        try {
          if (cur_dialog.fields_dict['from_date']) cur_dialog.set_value('from_date', payload.from);
          if (cur_dialog.fields_dict['to_date'])   cur_dialog.set_value('to_date',   payload.to);

          var viewVal = (payload.view === 'qty') ? 'qty' : 'amt';
          if (cur_dialog.fields_dict['metric']) {
    cur_dialog.set_value('metric', viewVal);
}
          if (cur_dialog.fields_dict['view_type']) cur_dialog.set_value('view_type', viewVal);
          if (cur_dialog.fields_dict['metric']) {
            cur_dialog.set_value('metric', viewVal);
            if (cur_dialog.fields_dict['metric'].$input) {
              cur_dialog.fields_dict['metric'].$input.trigger('change');
            }
          }
          if (cur_dialog.fields_dict['company']) {
            cur_dialog.set_value('company', payload.company || '');
          }
          if (cur_dialog.fields_dict['month']) {
            var m = payload.from ? String(new Date(payload.from).getMonth() + 1) : '';
            cur_dialog.set_value('month', m);
          }
        } catch(e) {
          console.error('Set value error:', chartName, e);
        }

        // ✅ Delay 400ms → 150ms — values settle hone ke baad button click
        setTimeout(function() {
          hideBackdrop();
          try {
            var btn = cur_dialog.$wrapper
                        ? cur_dialog.$wrapper.find('.btn-modal-primary')[0]
                        : null;
            if (btn) {
              btn.click();
            } else {
              var fb = cur_dialog.$wrapper
                         ? cur_dialog.$wrapper.find('.btn-primary')[0]
                         : null;
              if (fb) fb.click();
            }
          } catch(e) {
            console.error('Button click error:', chartName, e);
          }

          // ✅ Delay 500ms → 250ms — next chart pe move karo
          setTimeout(function() {
            try {
              if (cur_dialog && cur_dialog.$wrapper) {
                cur_dialog.$wrapper.removeClass('dr-offscreen');
              }
              if (cur_dialog) cur_dialog.hide();
            } catch(e) {}
            hideBackdrop();
            document.querySelectorAll('.modal-backdrop').forEach(function(el) { el.remove(); });
            processNext();
          }, 250);

        }, 150);

      }, 50); // ✅ Poll interval 80ms → 50ms

    }, 50); // ✅ Initial delay 200ms → 50ms
  }

  processNext();
}

function applyFilter() {
      console.log("applyFilter called");

  if (drState.preset === 'custom') {
    var f = sel('dr-from-date').value.trim();
    var t = sel('dr-to-date').value.trim();
    if (!f || !t) {
      frappe.msgprint(__('Please select both From and To dates.'));
      return;
    }
    var fd = new Date(f), td = new Date(t);
    if (td < fd) {
      frappe.msgprint(__('To date must be after From date.'));
      return;
    }
    drState.from = f;
    drState.to   = t;
    sel('dr-btn-label').textContent = fmt(fd) + ' \u2013 ' + fmt(td);
  }

  sessionStorage.setItem('dr_from',    drState.from);
  sessionStorage.setItem('dr_to',      drState.to);
  sessionStorage.setItem('dr_preset',  drState.preset);
  sessionStorage.setItem('dr_view',    drState.view);
  sessionStorage.setItem('dr_label',   sel('dr-btn-label').textContent);
  sessionStorage.setItem('dr_company', drState.company);

  closeDropdown();

  var payload = {
    from   : drState.from,
    to     : drState.to,
    view   : drState.view,
    company: drState.company
  };

  frappe.dashboardFilter = payload;
  document.dispatchEvent(new CustomEvent('dashboardFilterChanged', { detail: payload }));

  refreshDashboardChart(payload);
}

function cancelDropdown() {
  closeDropdown();
}

function setView(v) {
  drState.view = v;
  sel('dr-btn-qty').classList.toggle('dr-toggle-active', v === 'qty');
  sel('dr-btn-amt').classList.toggle('dr-toggle-active', v === 'amt');
  applyFilter();
}

function loadCompanies() {
  var select = sel('dr-company-select');
  select.innerHTML = '<option value="">-- Loading... --</option>';

  var savedCompany = sessionStorage.getItem('dr_company');
  var userCompany  = frappe.defaults.get_user_default('company') ||
                     frappe.defaults.get_default('company') || '';

  var isAdmin = frappe.session.user === 'Administrator';
  var isTZU   = userCompany === 'TZU Lifestyle Private Limited';

  if (isAdmin || isTZU) {
    loadAllCompanies(select, savedCompany || userCompany);
  } else {
    loadUserCompany(select, userCompany);
  }
}

function loadAllCompanies(select, companyToSelect) {
  frappe.call({
    method: 'frappe.client.get_list',
    args: {
      doctype          : 'Company',
      fields           : ['name'],
      limit_page_length: 500,
      order_by         : 'name asc'
    },
    callback: function(r) {
      select.innerHTML     = '<option value="">-- All Companies --</option>';
      select.disabled      = false;
      select.style.opacity = '1';
      select.style.cursor  = 'pointer';

      if (r && r.message && r.message.length > 0) {
        r.message.forEach(function(row) {
          var opt = document.createElement('option');
          opt.value       = row.name;
          opt.textContent = row.name;
          select.appendChild(opt);
        });
        if (companyToSelect) {
          select.value    = companyToSelect;
          drState.company = companyToSelect;
        }
      }
    }
  });
}

function loadUserCompany(select, company) {
  select.innerHTML = '';
  var opt = document.createElement('option');
  opt.value       = company;
  opt.textContent = company || '-- No Company --';
  select.appendChild(opt);
  select.disabled      = true;
  select.style.opacity = '0.7';
  select.style.cursor  = 'not-allowed';
  drState.company = company;
}

var drMainBtn = sel("dr-main-btn");

if (drMainBtn) {

    drMainBtn.addEventListener("click", function(e){

        e.stopPropagation();

        toggleDropdown();

    });

}

PRESET_IDS.forEach(function(p) {
  var el = sel('dr-opt-' + p);
  if (el) {
    el.addEventListener('click', function(e) {
      e.stopPropagation();
      selectPreset(p);
    });
  }
});

sel('dr-apply-btn').addEventListener('click', function(e) {
  e.stopPropagation();
  applyFilter();
});

sel('dr-cancel-btn').addEventListener('click', function(e) {
  e.stopPropagation();
  cancelDropdown();
});

var qtyBtn = sel("dr-btn-qty");

if (qtyBtn) {

    qtyBtn.addEventListener("click", function(){

        setView("qty");

    });

}
var amtBtn = sel("dr-btn-amt");

if (amtBtn) {

    amtBtn.addEventListener("click", function(){

        setView("amt");

    });

}

var companySelect = sel("dr-company-select");

if (companySelect) {

    companySelect.addEventListener("change", function(){

        drState.company = this.value;

        sessionStorage.setItem(
            "dr_company",
            this.value
        );

        closeDropdown();

        setTimeout(function(){

            applyFilter();

        },300);

    });

}

document.addEventListener('click', function(e) {
  var wrap = root_element.querySelector('.dr-container');
  var path = e.composedPath ? e.composedPath() : [];
  var insideWrap = path.indexOf(wrap) !== -1;
  if (drState.dropOpen && !insideWrap) closeDropdown();
});

(function init() {
  var savedFrom    = sessionStorage.getItem('dr_from');
  var savedTo      = sessionStorage.getItem('dr_to');
  var savedPreset  = sessionStorage.getItem('dr_preset');
  var savedView    = sessionStorage.getItem('dr_view');
  var savedLabel   = sessionStorage.getItem('dr_label');
  var savedCompany = sessionStorage.getItem('dr_company');

  if (savedFrom && savedTo) {
    drState.from    = savedFrom;
    drState.to      = savedTo;
    drState.preset  = savedPreset  || 'thismonth';
    drState.view    = savedView    || 'qty';
    drState.company = savedCompany || '';
    sel('dr-btn-label').textContent = savedLabel || (savedFrom + ' \u2013 ' + savedTo);
    setActiveOption(drState.preset);
    sel('dr-btn-qty').classList.toggle('dr-toggle-active', drState.view === 'qty');
    sel('dr-btn-amt').classList.toggle('dr-toggle-active', drState.view === 'amt');
  } else {
    var dates = getPresetDates('thismonth');
    drState.from = isoDate(dates[0]);
    drState.to   = isoDate(dates[1]);
    sel('dr-btn-label').textContent = fmt(dates[0]) + ' \u2013 ' + fmt(dates[1]);
    setActiveOption('thismonth');
    sel('dr-btn-qty').classList.add('dr-toggle-active');
  }

  if (frappe.ready) {
    frappe.ready(function() { loadCompanies(); });
  } else {
    setTimeout(loadCompanies, 800);
  }
})();

