script:
(function () {

    /* =========================================================
       HELPERS
    ========================================================= */

    function getContainer(selector) {
        return root_element.querySelector(selector);
    }


    function getDashboardFilters(event_payload) {

        event_payload = event_payload || {};

        let from = "";
        let to = "";
        let company = "";
        let view = "qty";


        /* -----------------------------------------------------
           1. LIVE GLOBAL FILTER
        ----------------------------------------------------- */

        if (frappe.dashboardFilter) {

            from =
                frappe.dashboardFilter.from_date ||
                frappe.dashboardFilter.from ||
                "";

            to =
                frappe.dashboardFilter.to_date ||
                frappe.dashboardFilter.to ||
                "";

            company =
                frappe.dashboardFilter.company ||
                "";

            view =
                frappe.dashboardFilter.view ||
                frappe.dashboardFilter.view_type ||
                frappe.dashboardFilter.metric ||
                "qty";
        }


        /* -----------------------------------------------------
           2. EVENT FILTER
        ----------------------------------------------------- */

        from =
            from ||
            event_payload.from_date ||
            event_payload.from ||
            "";

        to =
            to ||
            event_payload.to_date ||
            event_payload.to ||
            "";

        company =
            company ||
            event_payload.company ||
            "";

        view =
            event_payload.view ||
            event_payload.view_type ||
            event_payload.metric ||
            view ||
            "qty";


        /* -----------------------------------------------------
           3. SESSION STORAGE
        ----------------------------------------------------- */

        from =
            from ||
            sessionStorage.getItem("dr_from") ||
            "";

        to =
            to ||
            sessionStorage.getItem("dr_to") ||
            "";

        company =
            company ||
            sessionStorage.getItem("dr_company") ||
            "";

        view =
            view ||
            sessionStorage.getItem("dr_view") ||
            "qty";


        /* -----------------------------------------------------
           4. DEFAULT DATE
        ----------------------------------------------------- */

        if (!from || !to) {

            const today =
                frappe.datetime.get_today();

            from =
                frappe.datetime.month_start(today);

            to =
                frappe.datetime.month_end(today);
        }


        /* -----------------------------------------------------
           5. DEFAULT COMPANY
        ----------------------------------------------------- */

        if (!company) {

            company =
                frappe.defaults.get_default("company") || "";
        }


        /* -----------------------------------------------------
           6. NORMALIZE VIEW
        ----------------------------------------------------- */

        if (
            view !== "qty" &&
            view !== "amt"
        ) {

            view = "qty";
        }


        return {
            from: from,
            to: to,
            company: company,
            view: view
        };
    }


    /* =========================================================
       GET REPORT DATA
    ========================================================= */

    function getReportData(response) {

        if (!response || !response.message) {
            return [];
        }

        const message = response.message;


        /* Standard Query Report result */

        if (
            Array.isArray(message.result)
        ) {
            return message.result;
        }


        /* Sometimes result itself is array */

        if (
            Array.isArray(message)
        ) {
            return message;
        }


        return [];
    }


    /* =========================================================
       GET ITEM NAME
    ========================================================= */

    function getItemName(row) {

        if (!row) {
            return "";
        }


        return (
            row.item_name ||
            row.item_code ||
            row.item ||
            row.style_no ||
            row.style_number ||
            row.custom_barcode_code ||
            ""
        );
    }


    /* =========================================================
       GET QUANTITY
    ========================================================= */

    function getQuantity(row) {

        if (!row) {
            return 0;
        }


        /*
         * IMPORTANT:
         * Check exact report field names first.
         */

        let qty =
            row.qty ??
            row.sales_qty ??
            row.total_qty ??
            row.stock_qty ??
            row.quantity ??
            row.value ??
            0;


        qty = parseFloat(qty);


        return isNaN(qty) ? 0 : qty;
    }


    /* =========================================================
       CLEAR / LOADING
    ========================================================= */

    function showLoading(container) {

        if (!container) {
            return;
        }

        container.innerHTML = `
            <div style="
                padding:15px;
                text-align:center;
                color:#888;
            ">
                Loading...
            </div>
        `;
    }


    /* =========================================================
       SHOW EMPTY
    ========================================================= */

    function showEmpty(container) {

        if (!container) {
            return;
        }

        container.innerHTML = `
            <div style="
                padding:15px;
                text-align:center;
                color:#888;
            ">
                No data available
            </div>
        `;
    }


    /* =========================================================
       SHOW ERROR
    ========================================================= */

    function showError(container) {

        if (!container) {
            return;
        }

        container.innerHTML = `
            <div style="
                padding:15px;
                text-align:center;
                color:#d9534f;
            ">
                Unable to load data
            </div>
        `;
    }


    /* =========================================================
       RENDER ITEM LIST
    ========================================================= */

    function renderItems(
        container,
        rows,
        sortAscending
    ) {

        if (!container) {
            return;
        }


        if (
            !rows ||
            !rows.length
        ) {

            showEmpty(container);

            return;
        }


        /*
         * Convert report rows into clean objects.
         */

        let items = rows
            .map(function (row) {

                return {
                    name: getItemName(row),
                    qty: getQuantity(row)
                };

            })
            .filter(function (item) {

                return item.name !== "";
            });


        if (!items.length) {

            showEmpty(container);

            return;
        }


        /*
         * Sort
         */

        items.sort(function (a, b) {

            if (sortAscending) {

                return a.qty - b.qty;

            }

            return b.qty - a.qty;

        });


        /*
         * Only top 5
         */

        items =
            items.slice(0, 5);


        let html = "";


        items.forEach(function (item, index) {

            html += `

                <div
                    class="tsi-row"
                    style="
                        display:flex;
                        align-items:center;
                        padding:10px 0;
                        border-bottom:1px solid #eee;
                    "
                >

                    <div
                        class="tsi-rank"
                        style="
                            width:35px;
                            font-weight:600;
                        "
                    >
                        ${index + 1}.
                    </div>


                    <div
                        class="tsi-item"
                        style="
                            flex:1;
                            font-weight:500;
                        "
                    >
                        ${frappe.utils.escape_html(
                            String(item.name)
                        )}
                    </div>


                    <div
                        class="tsi-qty"
                        style="
                            width:70px;
                            text-align:right;
                            font-weight:600;
                        "
                    >
                        ${item.qty}
                    </div>

                </div>

            `;

        });


        container.innerHTML = html;
    }


    /* =========================================================
       TOP SELLING
    ========================================================= */

    function loadTopSellingItems(filters) {

        const container =
            getContainer("#top-selling-items");


        if (!container) {
            console.warn(
                "Top Selling container not found"
            );

            return;
        }


        showLoading(container);


        frappe.call({

            method:
                "frappe.desk.query_report.run",

            args: {

                report_name:
                    "Top Selling Items 1",

                filters: {

                    from_date:
                        filters.from,

                    to_date:
                        filters.to,

                    company:
                        filters.company,

                    /*
                     * IMPORTANT FIX
                     */

                    metric:
                        filters.view === "amt"
                            ? "amt"
                            : "qty"
                },

                ignore_prepared_report: 1

            },

            callback: function (r) {

                console.log(
                    "Top Selling Items 1 Response:",
                    r.message
                );


                const data =
                    getReportData(r);


                renderItems(
                    container,
                    data,
                    false
                );

            },

            error: function (error) {

                console.error(
                    "Top Selling Items 1 Error:",
                    error
                );


                showError(container);

            }

        });

    }


    /* =========================================================
       LEAST SELLING
    ========================================================= */

    function loadLeastSellingItems(filters) {

        const container =
            getContainer("#least-selling-items");


        if (!container) {

            console.warn(
                "Least Selling container not found"
            );

            return;
        }


        showLoading(container);


        frappe.call({

            method:
                "frappe.desk.query_report.run",

            args: {

                report_name:
                    "Least Selling Items",

                filters: {

                    from_date:
                        filters.from,

                    to_date:
                        filters.to,

                    company:
                        filters.company,

                    /*
                     * IMPORTANT FIX
                     */

                    metric:
                        filters.view === "amt"
                            ? "amt"
                            : "qty"
                },

                ignore_prepared_report: 1

            },

            callback: function (r) {

                console.log(
                    "Least Selling Items Response:",
                    r.message
                );


                const data =
                    getReportData(r);


                renderItems(
                    container,
                    data,
                    true
                );

            },

            error: function (error) {

                console.error(
                    "Least Selling Items Error:",
                    error
                );


                showError(container);

            }

        });

    }


    /* =========================================================
       REFRESH BOTH
    ========================================================= */

    function refreshTopLeastSelling(
        event_payload
    ) {

        const filters =
            getDashboardFilters(
                event_payload
            );


        console.log(
            "Selling Items Filters:",
            filters
        );


        /*
         * Run both reports simultaneously.
         */

        loadTopSellingItems(
            filters
        );

        loadLeastSellingItems(
            filters
        );
    }


    /* =========================================================
       PREVENT DUPLICATE INITIAL LOAD
    ========================================================= */

    let initialized = false;


    function initialLoad() {

        if (initialized) {
            return;
        }

        initialized = true;


        refreshTopLeastSelling();
    }


    /* =========================================================
       INITIAL LOAD
    ========================================================= */

    /*
     * root_element is already available when
     * Custom HTML Block JS executes.
     *
     * Small timeout only to allow Date Range
     * block to save its filters.
     */

    setTimeout(function () {

        initialLoad();

    }, 100);


    /* =========================================================
       DASHBOARD FILTER CHANGE
    ========================================================= */

    document.addEventListener(
        "dashboardFilterChanged",
        function (e) {

            console.log(
                "Selling Items → Filter Changed",
                e.detail
            );


            refreshTopLeastSelling(
                e.detail || {}
            );

        }
    );


    /* =========================================================
       SELLING DASHBOARD READY
    ========================================================= */

    document.addEventListener(
        "sellingDashboardReady",
        function (e) {

            console.log(
                "Selling Items → Dashboard Ready",
                e.detail
            );


            refreshTopLeastSelling(
                e.detail || {}
            );

        }
    );

})();

